def initialize_weights(model, config):
    """Depth-Adaptive Residual Scaling (DARS) initialization.

    For residual networks: scale conv weights by (1 + layer_depth/total_depth)^(-0.5)
    to gradually increase variance with depth while controlling accumulation.
    BatchNorm: weight=1, bias=small positive (0.01).
    Linear: Kaiming normal fan_in.
    """
    arch = config['arch']
    total_depth = config['depth']

    # First pass: collect conv layers and assign depth indices
    conv_layers = []
    for name, module in model.named_modules():
        if isinstance(module, nn.Conv2d):
            conv_layers.append((name, module))

    # Initialize all convs with Kaiming normal first
    for name, module in model.named_modules():
        if isinstance(module, nn.Conv2d):
            nn.init.kaiming_normal_(module.weight, mode='fan_out', nonlinearity='relu')
        elif isinstance(module, nn.BatchNorm2d):
            nn.init.constant_(module.weight, 1.0)
            nn.init.constant_(module.bias, 0.01)
        elif isinstance(module, nn.Linear):
            nn.init.kaiming_normal_(module.weight, mode='fan_in', nonlinearity='relu')
            if module.bias is not None:
                nn.init.constant_(module.bias, 0.0)

    # Apply depth scaling for residual architectures
    if arch.startswith('resnet') or arch == 'mobilenetv2':
        for idx, (name, module) in enumerate(conv_layers):
            depth_factor = (1.0 + idx / total_depth) ** 0.5  # sqrt of depth factor
            module.weight.data.div_(depth_factor)

def initialize_weights(model, config):
    """Residual-Aware Fixup++ initialization.

    For residual networks: apply Fixup scaling to conv layers inside residual blocks.
    Additionally, scale shortcut projections by sqrt(0.5).
    BatchNorm: weight=1, bias=0 (except last BN in block zero-init).
    Linear: Kaiming normal fan_in.
    """
    arch = config['arch']
    is_residual = arch.startswith('resnet') or arch == 'mobilenetv2'

    # First pass: count residual blocks
    block_count = 0
    for m in model.modules():
        if isinstance(m, BasicBlock) or isinstance(m, InvertedResidual):
            block_count += 1

    # Second pass: initialize
    for m in model.modules():
        if isinstance(m, nn.Conv2d):
            nn.init.kaiming_normal_(m.weight, mode='fan_out', nonlinearity='relu')
            # Scale shortcuts
            if is_residual and m.kernel_size == (1, 1):
                m.weight.data.mul_(0.5**0.5)  # sqrt(0.5)
        elif isinstance(m, nn.BatchNorm2d):
            nn.init.constant_(m.weight, 1.0)
            nn.init.constant_(m.bias, 0.0)
        elif isinstance(m, nn.Linear):
            nn.init.kaiming_normal_(m.weight, mode='fan_in', nonlinearity='relu')
            if m.bias is not None:
                nn.init.constant_(m.bias, 0.0)

    # Fixup scaling for residual blocks
    if is_residual and block_count > 0:
        fixup_scale = block_count ** (-0.5)
        for m in model.modules():
            if isinstance(m, BasicBlock):
                m.conv2.weight.data.mul_(fixup_scale)
                nn.init.constant_(m.bn2.weight, 0.0)
            elif isinstance(m, InvertedResidual):
                # Scale last conv in the block (the 1x1 pointwise conv)
                last_conv = None
                for sub in m.conv.modules():
                    if isinstance(sub, nn.Conv2d):
                        last_conv = sub
                if last_conv:
                    last_conv.weight.data.mul_(fixup_scale)
                # Zero-init last BN in block
                for sub in reversed(list(m.conv.modules())):
                    if isinstance(sub, nn.BatchNorm2d):
                        nn.init.constant_(sub.weight, 0.0)
                        break

def initialize_weights(model, config):
    """Depth-Adaptive Variance Scaling (DAVS) initialization.

    For all conv layers: scale variance by (1 + layer_depth/total_depth)^(-alpha)
    where alpha=0.25 provides gentle depth adjustment.
    BatchNorm: weight=1, bias=0.
    Linear: Kaiming normal fan_in.
    """
    arch = config['arch']
    total_depth = config['depth']
    alpha = 0.25

    # Collect conv layers
    conv_layers = []
    for name, module in model.named_modules():
        if isinstance(module, nn.Conv2d):
            conv_layers.append(module)

    # Initialize all layers
    for module in model.modules():
        if isinstance(module, nn.Conv2d):
            nn.init.kaiming_normal_(module.weight, mode='fan_out', nonlinearity='relu')
        elif isinstance(module, nn.BatchNorm2d):
            nn.init.constant_(module.weight, 1.0)
            nn.init.constant_(module.bias, 0.0)
        elif isinstance(module, nn.Linear):
            nn.init.kaiming_normal_(module.weight, mode='fan_in', nonlinearity='relu')
            if module.bias is not None:
                nn.init.constant_(module.bias, 0.0)

    # Apply depth scaling
    for idx, conv in enumerate(conv_layers):
        depth_factor = (1.0 + idx / total_depth) ** alpha
        conv.weight.data.div_(depth_factor)

def initialize_weights(model, config):
    """Residual Branch Balancing (RBB) initialization.

    For residual networks: scale last conv in each residual block by L^(-0.5)
    where L is number of blocks (Fixup). Additionally scale shortcut convs by L^(-0.5).
    Zero-init last BN in each block.
    For VGG: standard Kaiming.
    """
    arch = config['arch']
    is_res = arch.startswith('resnet') or arch == 'mobilenetv2'

    # Count residual blocks
    L = 0
    for m in model.modules():
        if isinstance(m, BasicBlock) or isinstance(m, InvertedResidual):
            L += 1

    # Kaiming init for all
    for m in model.modules():
        if isinstance(m, nn.Conv2d):
            nn.init.kaiming_normal_(m.weight, mode='fan_out', nonlinearity='relu')
        elif isinstance(m, nn.BatchNorm2d):
            nn.init.constant_(m.weight, 1.0)
            nn.init.constant_(m.bias, 0.0)
        elif isinstance(m, nn.Linear):
            nn.init.kaiming_normal_(m.weight, mode='fan_in', nonlinearity='relu')
            if m.bias is not None:
                nn.init.constant_(m.bias, 0.0)

    if is_res and L > 0:
        scale = L ** (-0.5)
        # Scale residual block convs and shortcuts
        for m in model.modules():
            if isinstance(m, BasicBlock):
                m.conv2.weight.data.mul_(scale)
                nn.init.constant_(m.bn2.weight, 0.0)
                # shortcut conv if present
                if len(m.shortcut) > 0:
                    for subm in m.shortcut:
                        if isinstance(subm, nn.Conv2d):
                            subm.weight.data.mul_(scale)
            elif isinstance(m, InvertedResidual):
                # Find last conv in block
                last_conv = None
                for subm in m.conv.modules():
                    if isinstance(subm, nn.Conv2d):
                        last_conv = subm
                if last_conv:
                    last_conv.weight.data.mul_(scale)
                # Zero-init last BN in block
                for subm in reversed(list(m.conv.modules())):
                    if isinstance(subm, nn.BatchNorm2d):
                        nn.init.constant_(subm.weight, 0.0)
                        break

def initialize_weights(model, config):
    """Depth-Aware Fixup Scaling (DAFS) initialization.

    For residual networks: scale last conv in each block by (L^(-0.5)) * (i/L)^(-0.25)
    where i is block index (1-indexed). This gives more scaling to later blocks.
    Zero-init last BN in each block.
    """
    arch = config['arch']
    is_res = arch.startswith('resnet') or arch == 'mobilenetv2'

    # Collect residual blocks
    blocks = []
    for m in model.modules():
        if isinstance(m, BasicBlock) or isinstance(m, InvertedResidual):
            blocks.append(m)
    L = len(blocks)

    # Kaiming init for all
    for m in model.modules():
        if isinstance(m, nn.Conv2d):
            nn.init.kaiming_normal_(m.weight, mode='fan_out', nonlinearity='relu')
        elif isinstance(m, nn.BatchNorm2d):
            nn.init.constant_(m.weight, 1.0)
            nn.init.constant_(m.bias, 0.0)
        elif isinstance(m, nn.Linear):
            nn.init.kaiming_normal_(m.weight, mode='fan_in', nonlinearity='relu')
            if m.bias is not None:
                nn.init.constant_(m.bias, 0.0)

    if is_res and L > 0:
        base_scale = L ** (-0.5)
        for i, blk in enumerate(blocks):
            depth_factor = ((i + 1) / L) ** (-0.25)  # i+1 to avoid zero
            scale = base_scale * depth_factor
            if isinstance(blk, BasicBlock):
                blk.conv2.weight.data.mul_(scale)
                nn.init.constant_(blk.bn2.weight, 0.0)
            elif isinstance(blk, InvertedResidual):
                # Find last conv
                last_conv = None
                for subm in blk.conv.modules():
                    if isinstance(subm, nn.Conv2d):
                        last_conv = subm
                if last_conv:
                    last_conv.weight.data.mul_(scale)
                # Zero-init last BN
                for subm in reversed(list(blk.conv.modules())):
                    if isinstance(subm, nn.BatchNorm2d):
                        nn.init.constant_(subm.weight, 0.0)
                        break

